float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float vnoise(float2 p)
{
    float2 c = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(c);
    float b = hash21(c + float2(1.0, 0.0));
    float d = hash21(c + float2(0.0, 1.0));
    float e = hash21(c + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(d, e, u.x), u.y);
}

float fbm(float2 p)
{
    float v = 0.0;
    float a = 0.5;
    for (int k = 0; k < 3; k++) { v += a * vnoise(p); p = p * 2.07 + float2(3.1, 7.7); a *= 0.5; }
    return v;
}

// görünen iz: x = 0 kuyruk → 1 baş (görünmüyorsa < 0), y = maske
float2 trail(float u, float head, float life)
{
    float eat = saturate((life - _Eat) / max(1.0 - _Eat, 0.001));
    float tailS = max(head - _Tail, eat * 1.02);
    float len = max(head - tailS, 0.001);
    float k = (u - tailS) / len;
    float m = smoothstep(0.0, 0.08, k) * (1.0 - smoothstep(head, head + 0.015, u)) * step(tailS, u);
    return float2(k, m);
}

