float4 frag(UPEInput i)
{
    float u = i.uv.x;
    float v = i.uv.y;
    float head = i.custom.x;
    float life = 1.0 - i.color.a;
    float2 tr = trail(u, head, life);
    float k = saturate(tr.x);
    float ramp = pow(k, 1.6);

    // lifler: yay boyunca uzayıp başa doğru akar
    float flow = u * 6.0 - i.time * _Scroll;
    float fib = saturate(fbm(float2(v * _Fiber, flow)) * 1.25 - 0.1);

    float w = _Width * (0.3 + 0.7 * k);
    float inner = 1.0 - w * (0.85 + (fib - 0.5) * 0.4);
    float body = smoothstep(inner - 0.02, inner + 0.12, v) * (1.0 - smoothstep(0.975, 1.0, v));
    float d = saturate((v - inner) / max(1.0 - inner, 0.001));
    float edge = 1.0 - smoothstep(0.0, _EdgeW * (0.4 + 0.6 * k), abs(v - (0.985 - _EdgeW * 0.3)));
    // ikinci ince çizgi (gövdenin ortasında, kopuk)
    float line2 = (1.0 - smoothstep(0.0, 0.006, abs(v - (1.0 - w * 0.45)))) * step(0.45, vnoise(float2(u * 10.0, 2.0))) * 0.35;

    float er = fbm(float2(u * 9.0, v * 6.0 - i.time * 1.2));
    float erodeM = saturate((er + 0.55 - life * 1.1) * 5.0);
    float fadeAll = 1.0 - smoothstep(0.55, 1.0, life);

    float3 col = _Body.rgb * body * pow(d, 1.3) * (0.35 + 0.65 * fib) + _Edge.rgb * (edge + line2) * (0.5 + 0.5 * k);
    col *= tr.y * ramp * erodeM * fadeAll * i.color.rgb;
    return float4(col, 1.0);
}
